import React, { useRef, useEffect } from 'react';
import { Card, CardHeader, CardFooter, Image } from "@nextui-org/react";
import { gsap } from 'gsap';

interface CardProps {
  title: string;
  description: string;
  image: string;
  footerTitle: string;
  footerDescription: string;
  footerImage: string;
}

const CustomCard: React.FC<CardProps> = ({ title, description, image, footerTitle }) => {
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const card = cardRef.current;

    const handleMouseEnter = () => {
      gsap.to(card, { scale: 1.01, duration: 0.3, ease: 'power1.inOut' });
    };

    const handleMouseLeave = () => {
      gsap.to(card, { scale: 1, duration: 0.3, ease: 'power1.inOut' });
    };

    card?.addEventListener('mouseenter', handleMouseEnter);
    card?.addEventListener('mouseleave', handleMouseLeave);

    return () => {
      card?.removeEventListener('mouseenter', handleMouseEnter);
      card?.removeEventListener('mouseleave', handleMouseLeave);
    };
  }, []);

  return (
    <div ref={cardRef}>
      <Card isFooterBlurred className="w-4/3 h-[500px] col-span-12 sm:col-span-7 h-[50vh] sm:h-[35vh] md:h-[50vh] lg:h-[20vh] xl:h-[50vh] 2xl:h-[50vh]">
        <CardHeader className="absolute z-10 top-1 flex-col items-start">
          <h1 className="text-white font-medium text-lg sm:text-xl md:text-2xl lg:text-3xl xl:text-4xl" style={{ fontWeight: "650" }}>
            {title}
          </h1>
        </CardHeader>
        <div className="corner-blur">
          <Image
            removeWrapper
            alt={title}
            className="z-0 w-full h-full object-cover"
            src={image}
          />
        </div>
        <CardFooter className="absolute bg-black/40 bottom-0 z-10 border-t-1 border-default-600 dark:border-default-100">
          <div className="flex flex-grow gap-2 items-center">
            <div className="flex flex-col">
              <p className="text-tiny text-white/60">{footerTitle}</p>
              <p className="text-tiny text-white/60">{description}</p>
            </div>
          </div>
        </CardFooter>
      </Card>
    </div>
  );
};

export default CustomCard;